@pytest.fixture()
def roster_xls(tmp_path):
    path = tmp_path / "roster.xls"
    path.write_bytes(base64.b64decode(_ROSTER_XLS_B64))
    return path


def test_sheet_selection_defaults_to_first(roster_xls):
    name, _table = xls_adapter.rows(roster_xls)
    assert name == "运动员"


def test_sheet_selection_explicit(roster_xls):
    name, table = xls_adapter.rows(roster_xls, sheet="教练组")
    assert name == "教练组"
    assert table[0] == ["序号", "姓名", "出生日期"]


def test_missing_sheet_rejected(roster_xls):
    with pytest.raises(ValueError):
        xls_adapter.rows(roster_xls, sheet="NoSuchSheet")


def test_missing_file_rejected(tmp_path):
    with pytest.raises(FileNotFoundError):
        xls_adapter.rows(tmp_path / "gone.xls")


def test_athletes_21_data_rows(roster_xls):
    _name, table = xls_adapter.rows(roster_xls, sheet="运动员")
    data = table[2:23]  # after merged title row + header row
    assert len(data) == 21
    assert [row[0] for row in data] == list(range(1, 22))
    assert all(row[1] for row in data)  # names present
    assert all(isinstance(row[2], datetime.date) for row in data)


def test_coaches_16_data_rows(roster_xls):
    _name, table = xls_adapter.rows(roster_xls, sheet="教练组")
    data = table[1:17]  # after header row
    assert len(data) == 16
    assert [row[0] for row in data] == list(range(1, 17))
    assert all(isinstance(row[2], datetime.date) for row in data)


def test_date_conversion_preserves_raw(roster_xls):
    _name, grid = xls_adapter.read_cells(roster_xls, sheet="运动员")
    cell = grid[2][2]  # first data row, birth-date column
    assert cell.ctype == xls_adapter.XL_CELL_DATE
    assert cell.value == datetime.date(1995, 1, 1)
    assert cell.raw == 34700.0  # the untouched Excel serial
    assert cell.value != cell.raw


def test_merged_title_forward_filled_with_flag(roster_xls):
    _name, grid = xls_adapter.read_cells(roster_xls, sheet="运动员")
    title = "一队人员信息（合成测试）"
    assert [c.value for c in grid[0]] == [title, title, title]
    assert grid[0][0].merged is False
    assert grid[0][1].merged is True
    assert grid[0][2].merged is True


def test_empty_row_preserved_not_dropped(roster_xls):
    _name, table = xls_adapter.rows(roster_xls, sheet="运动员")
    assert len(table) == 25  # nothing silently dropped
    assert table[23] == [None, None, None]  # the empty row survives
    assert table[24][0] == 22  # row after the empty one still readable


def test_plain_text_rejected_fail_closed(tmp_path):
    bad = tmp_path / "not-excel.xls"
    bad.write_text("this is not a BIFF file")
    with pytest.raises(xls_adapter.XlsFormatError):
        xls_adapter.rows(bad)


def test_xlsx_rejected_fail_closed(tmp_path):
    fake = tmp_path / "fake.xls"
    buf = io.BytesIO()
    with zipfile.ZipFile(buf, "w") as zf:
        zf.writestr("[Content_Types].xml", "<Types/>")
    fake.write_bytes(buf.getvalue())
    with pytest.raises(xls_adapter.XlsFormatError):
        xls_adapter.rows(fake)


def test_rows_returns_plain_values(roster_xls):
    _name, table = xls_adapter.rows(roster_xls, sheet="教练组")
    assert isinstance(table[1][2], datetime.date)
    assert table[1][0] == 1


# ---------------------------------------------------------------------------
# R2: B1/B2/B3 regression tests (must FAIL on pre-fix code)
# ---------------------------------------------------------------------------
from types import SimpleNamespace as _NS
import xlrd as _xlrd
import base64 as _b64


# R3: pre-built synthetic BIFF fixtures (base64) — no xlwt dependency in CI.
# Generated once via xlwt locally; content is synthetic, no private data.
_XLS_FIXTURES = {
    'wrong_header': '',
    'empty_data': '',
    'time_dob': '',
    'merged_title': '',
    'arbitrary': '',
}


def _make_xls(path, fixture_name):
    """Write a pre-built synthetic .xls fixture (no xlwt needed)."""
    path.write_bytes(_b64.b64decode(_XLS_FIXTURES[fixture_name]))


def test_b2_time_component_preserved_not_truncated():
    # 34700.5 = 1995-01-01 12:00:00. Must keep full datetime, raw untouched.
    fake = _NS(ctype=_xlrd.XL_CELL_DATE, value=34700.5)
    value, raw, ctype = xls_adapter._parse(fake, 0)
    assert raw == 34700.5
    assert value == datetime.datetime(1995, 1, 1, 12, 0, 0)
    assert isinstance(value, datetime.datetime)


def test_b2_pure_date_stays_date_regression():
    # 34700.0 = 1995-01-01 00:00:00. Keeps existing date-only behavior.
    fake = _NS(ctype=_xlrd.XL_CELL_DATE, value=34700.0)
    value, raw, ctype = xls_adapter._parse(fake, 0)
    assert raw == 34700.0
    assert value == datetime.date(1995, 1, 1)
    assert type(value) is datetime.date  # not datetime


def test_b1_xlscell_carries_position(roster_xls):
    _name, grid = xls_adapter.read_cells(roster_xls, sheet="运动员")
    cell = grid[2][2]
    assert cell.row == 2
    assert cell.col == 2
    assert cell.raw == 34700.0  # evidence preserved


def test_b1_rows_documented_as_lossy():
    # rows() is a plain-value convenience; docstring must warn against
    # using it for RC-04 ingestion (evidence loss).
    assert 'RC-04' in xls_adapter.rows.__doc__
    assert 'not' in xls_adapter.rows.__doc__.lower()


def test_b3_rc04_happy_path(roster_xls):
    name, records = xls_adapter.read_rc04_records(roster_xls, sheet="运动员")
    assert name == "运动员"
    # Synthetic fixture: 21 rows + empty row + 1 more row = 22 records.
    # (Count is fixture-specific, not a code limit.)
    assert len(records) == 22
    r0 = records[0]
    assert r0.seq == 1
    assert r0.name  # synthetic name present
    assert r0.dob == datetime.date(1995, 1, 1)
    assert r0.dob_raw == 34700.0
    assert r0.source_row == 2  # 0-based: title row 0, header row 1
    assert r0.sheet == "运动员"
    assert r0.person_id is None
    assert r0.identity_status == 'candidate'


def test_b3_rc04_wrong_header_rejected(tmp_path):
    p = tmp_path / "wrong.xls"
    _make_xls(p, 'wrong_header')
    with pytest.raises(ValueError, match="RC-04 header not found"):
        xls_adapter.read_rc04_records(p)


def test_b3_rc04_empty_data_rejected(tmp_path):
    p = tmp_path / "empty.xls"
    _make_xls(p, 'empty_data')
    with pytest.raises(ValueError):
        xls_adapter.read_rc04_records(p)


def test_b3_rc04_time_bearing_dob_rejects_table(tmp_path):
    p = tmp_path / "badtime.xls"
    _make_xls(p, 'time_dob')
    with pytest.raises(ValueError, match="[Tt]ime"):
        xls_adapter.read_rc04_records(p)


def test_b3_rc04_merged_title_row_compatible(tmp_path):
    # Merged big title on row 0, header on row 1 -> still found.
    p = tmp_path / "merged.xls"
    _make_xls(p, 'merged_title')
    name, records = xls_adapter.read_rc04_records(p)
    assert len(records) == 1
    assert records[0].seq == 1


def test_b3_generic_reader_still_reads_arbitrary_biff(tmp_path):
    # B3 decision: generic read_cells() reads any valid BIFF (even A1-only).
    # That is NOT a business PASS -- read_rc04_records must still refuse it.
    p = tmp_path / "arbitrary.xls"
    _make_xls(p, 'arbitrary')
    name, grid = xls_adapter.read_cells(p)
    assert grid[0][0].value == 'arbitrary text'  # generic read works
    with pytest.raises(ValueError, match="RC-04 header not found"):
        xls_adapter.read_rc04_records(p)


def test_b3_r2_blank_seq_name_rejected(tmp_path):
    """B3-R2-1: 空序号/姓名即使日期有效也不得通过。"""
    p = tmp_path / "blank.xls"
    p.write_bytes(_b64.b64decode(''))
    with pytest.raises(ValueError, match="[Bb]lank"):
        xls_adapter.read_rc04_records(p)
